BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';

ALTER TYPE public."RoleType" ADD VALUE IF NOT EXISTS 'pricing_editor';

-- Cast the existing enum column to text so this constraint can be added in
-- the same transaction without using a newly added enum literal before commit.
-- Existing role_assignment_scope_shape_check and
-- role_assignment_project_matches_unit remain unchanged and in force.
ALTER TABLE public.role_assignment
  ADD CONSTRAINT role_assignment_pricing_editor_scope_check
  CHECK (
    role::text <> 'pricing_editor'
    OR (
      ((scope_type = 'project' AND project_id IS NOT NULL AND unit_id IS NULL)
        OR (scope_type = 'unit' AND project_id IS NOT NULL AND unit_id IS NOT NULL))
      AND organization_id IS NULL
      AND provider_id IS NULL
    )
  ) NOT VALID;

ALTER TABLE public.role_assignment
  VALIDATE CONSTRAINT role_assignment_pricing_editor_scope_check;
COMMIT;
